CREATE PROCEDURE p_sum_qty
AS
BEGIN
    DECLARE @id INT, @q INT, @tot INT;
    SET @tot = 0;

    DECLARE c1 CURSOR FOR
    SELECT id, qty FROM item ORDER BY id;
    OPEN c1;

    FETCH c1 INTO @id, @q;
    WHILE (@@CURSORSTATUS = 0)
    BEGIN
        SET @tot = @tot + @q;
        FETCH c1 INTO @id, @q;
    END;

    CLOSE c1;
    DEALLOCATE c1;

    SELECT @tot AS total;
END;
GO

