CREATE PROCEDURE p_bal @id INT, @bal INT OUTPUT
AS
BEGIN
    DECLARE @bal INT;
    SELECT @bal = bal FROM acct WHERE id = @id;
    IF @@ROWCOUNT = 0
        BEGIN
            SET @bal = NULL;
            RETURN 1;
        END
    ELSE
        BEGIN
            SET @bal = ISNULL(@bal, 0);
            RETURN 0;
        END
END

